"""Benchmark descartável: custo real da regra A por sequência, um request por vez.

Roda a partir da raiz do repo deciframe (importa main.py, que exige cwd correto).
"""
import statistics
import sys
import time

import main


def bloco_substring(seq, cifra):
    return ';'.join(t.lower() for t in seq) in ';'.join(t.lower() for t in cifra)


def bloco_token(seq, cifra):
    n = len(seq)
    seq_l = [t.lower() for t in seq]
    cifra_l = [t.lower() for t in cifra]
    for i in range(len(cifra_l) - n + 1):
        if cifra_l[i:i + n] == seq_l:
            return True
    return False


def vocab_exato(seq, musica):
    return len(musica.acordes) == len(set(seq)) and all(a.lower() in {t.lower() for t in seq} for a in musica.acordes)


def regra_a_string(seq, musica):
    return bloco_substring(seq, musica.cifra) and vocab_exato(seq, musica)


def regra_a_token(seq, musica):
    return bloco_token(seq, musica.cifra) and vocab_exato(seq, musica)


def regra_c_token(seq, musica):
    return bloco_token(seq, musica.cifra)


def conta(regra, seq, collection):
    return [m.id_unico_musica for m in collection if regra(seq, m)]


SEQS = [
    ['Bm', 'G', 'D', 'A'],
    ['C', 'G', 'Am', 'F'],
    ['Em', 'G'],
    ['C', 'A7', 'Dm', 'G7'],
    ['Gm', 'F'],
    ['C', 'C7', 'F', 'Fm'],
]


def tempo(fn, repeticoes=5):
    amostras = []
    for _ in range(repeticoes):
        t0 = time.perf_counter()
        fn()
        amostras.append((time.perf_counter() - t0) * 1000)
    return statistics.median(amostras), min(amostras)


def main_bench():
    collection = main.apply_filtro(main.musicas.values(), main.generos)
    print('python', sys.version.split()[0], '| musicas na colecao:', len(collection))

    # 1) contagem e conferencia contra a tag (regra A string vs token)
    tag = {}
    for i, seq in enumerate(SEQS):
        tag[i] = {m.id_unico_musica for m in main.musicas.values() if str(i) in m.seqs_famosas}
    print('tag por sequencia:', [len(tag[i]) for i in range(6)], 'total', sum(len(v) for v in tag.values()))

    for nome, regra in (('A string', regra_a_string), ('A token', regra_a_token)):
        total = 0
        difs = []
        for i, seq in enumerate(SEQS):
            ids = set(conta(regra, seq, collection))
            total += len(ids)
            difs.append(len(ids ^ tag[i]))
        print('%s: total %d | diff simetrica por seq %s' % (nome, total, difs))

    # 2) tempo
    def uma_seq_string():
        for m in collection:
            regra_a_string(SEQS[0], m)

    def uma_seq_token():
        for m in collection:
            regra_a_token(SEQS[0], m)

    def seis_uma_passada_string():
        for m in collection:
            for seq in SEQS:
                regra_a_string(seq, m)

    def seis_uma_passada_token():
        for m in collection:
            for seq in SEQS:
                regra_a_token(seq, m)

    for nome, fn in (
        ('A string, 1 seq', uma_seq_string),
        ('A token,  1 seq', uma_seq_token),
        ('A string, 6 seqs numa passada', seis_uma_passada_string),
        ('A token,  6 seqs numa passada', seis_uma_passada_token),
    ):
        med, mn = tempo(fn)
        print('%-32s mediana %7.1f ms | min %7.1f ms | por seq %6.1f ms' % (nome, med, mn, med / (1 if '1 seq' in nome else 6)))

    # 3) casos de borda da pesquisa (§2.8)
    for seq in (['C'], ['Am'], ['G', 'G'], ['Cb'], ['H']):
        print('regra A token', seq, '->', len(conta(regra_a_token, seq, collection)))

    # 4) artefato de prefixo: ultimo token da seq e prefixo de outro token dela
    for seq in (['A7', 'D', 'A'], ['C', 'C7', 'F'], ['Em', 'G']):
        s = set(conta(regra_a_string, seq, collection))
        t = set(conta(regra_a_token, seq, collection))
        print('artefato', seq, 'string', len(s), 'token', len(t), 'so_string', len(s - t))


main_bench()

