# -*- coding: utf-8 -*-
"""Benchmark descartavel: custo real da regra A por sequencia, um request por vez.

Roda a partir da raiz do repo deciframe. Compara tres implementacoes:
  A1  substring ingenua (como o gerador), lower() recalculado a cada musica
  A2  substring com ';' nas bordas  -> token-level exato
  A3  A2 + poda por vocabulario (candidatos) antes do teste de bloco
"""
import os
import statistics
import sys
import time

sys.path.insert(0, os.getcwd())
import main

SEQS = [
    ['Bm', 'G', 'D', 'A'],
    ['C', 'G', 'Am', 'F'],
    ['Em', 'G'],
    ['C', 'A7', 'Dm', 'G7'],
    ['Gm', 'F'],
    ['C', 'C7', 'F', 'Fm'],
]


class Prep(object):
    __slots__ = ('m', 'join', 'alvo', 'vocab')

    def __init__(self, m):
        self.m = m
        self.join = ';'.join(t.lower() for t in m.cifra)
        self.alvo = ';' + self.join + ';'
        self.vocab = frozenset(t.lower() for t in m.acordes)


def prep(collection):
    return [Prep(m) for m in collection]


def a1(seq, p):
    s = ';'.join(t.lower() for t in seq)
    if not all(a.lower() in {t.lower() for t in seq} for a in p.m.acordes):
        return False
    return s in ';'.join(t.lower() for t in p.m.cifra)


def a2(seq, p):
    s = ';' + ';'.join(t.lower() for t in seq) + ';'
    if not all(a.lower() in {t.lower() for t in seq} for a in p.m.acordes):
        return False
    return s in p.alvo


def a3(seq, p, seq_needle=None, seq_vocab=None):
    if seq_needle is None:
        seq_vocab = frozenset(t.lower() for t in seq)
        seq_needle = ';' + ';'.join(t.lower() for t in seq) + ';'
    return p.vocab <= seq_vocab and seq_needle in p.alvo


def conta(regra, seq, preps):
    return [p.m.id_unico_musica for p in preps if regra(seq, p)]


def tempo(fn, repeticoes=7):
    amostras = []
    for _ in range(repeticoes):
        t0 = time.perf_counter()
        fn()
        amostras.append((time.perf_counter() - t0) * 1000)
    return statistics.median(amostras), min(amostras)


collection = main.apply_filtro(main.musicas.values(), main.generos)
preps = prep(collection)
print('python', sys.version.split()[0], '| musicas:', len(collection))

tag = {i: {m.id_unico_musica for m in main.musicas.values() if str(i) in m.seqs_famosas}
       for i in range(6)}
print('tag por seq:', [len(tag[i]) for i in range(6)], 'total', sum(len(v) for v in tag.values()))

for nome, regra in (('A1', a1), ('A2', a2), ('A3', a3)):
    total, difs = 0, []
    for i, seq in enumerate(SEQS):
        ids = set(conta(regra, seq, preps))
        total += len(ids)
        difs.append(len(ids ^ tag[i]))
    print('%s total %d | diff simetrica %s' % (nome, total, difs))

# custo por request: 1 sequencia, com pre-processamento por request (needle/vocab)
def um_a2(seq=SEQS[0]):
    needle = ';' + ';'.join(t.lower() for t in seq) + ';'
    vocab = frozenset(t.lower() for t in seq)
    for p in preps:
        if p.vocab <= vocab and needle in p.alvo:
            pass


def um_a1(seq=SEQS[0]):
    for p in preps:
        a1(seq, p)


def seis_a2():
    preparadas = [(';' + ';'.join(t.lower() for t in s) + ';', frozenset(t.lower() for t in s))
                  for s in SEQS]
    for p in preps:
        for needle, vocab in preparadas:
            if p.vocab <= vocab and needle in p.alvo:
                pass


for nome, fn, div in (
    ('A1 1 seq (ingenuo)', um_a1, 1),
    ('A2 1 seq (bordas ;)', um_a2, 1),
    ('A2 6 seqs, 1 passada', seis_a2, 6),
):
    med, mn = tempo(fn)
    print('%-24s mediana %6.1f ms | min %6.1f ms | por seq %6.1f ms' % (nome, med, mn, med / div))

# bordas (contagens ja conferidas contra a pesquisa §2.8)
for seq in (['C'], ['Am'], ['G', 'G'], ['Cb'], ['H']):
    print('a3', seq, '->', len(conta(a3, seq, preps)))

# artefato de prefixo
for seq in (['A7', 'D', 'A'], ['C', 'C7', 'F'], ['Em', 'G']):
    s = set(conta(a1, seq, preps))
    t = set(conta(a3, seq, preps))
    print('prefixo', seq, 'A1', len(s), 'A3', len(t), 'so_A1', len(s - t))
